import{_ as e,b as l,c as a,I as o}from"./chunks/framework.C6cPs9Ia.js";const h=JSON.parse('{"title":"阿罗娜，把白板擦一下——建站记","description":"柳卿烟的博客开张记，一个二次元高中生的蔚蓝档案基地","frontmatter":{"title":"阿罗娜，把白板擦一下——建站记","date":"2026-09-15T00:00:00.000Z","tags":["建站","日常"],"pinned":true,"cover":"/LQY/images/cover-a.jpg","head":[["meta",{"name":"description","content":"柳卿烟的博客开张记，一个二次元高中生的蔚蓝档案基地"}],["meta",{"name":"keywords","content":"建站, 博客, 蔚蓝档案, VitePress"}]]},"headers":[],"relativePath":"posts/hello-world.md","filePath":"posts/hello-world.md"}'),s={name:"posts/hello-world.md"};function i(r,t,n,c,d,p){return l(),a("div",null,[...t[0]||(t[0]=[o('<p>一个高中生的博客开张了。这里会记录追番、抽卡、月考和所有放学后的快乐。</p><hr><h2 id="首先是个自我介绍" tabindex="-1">首先是个自我介绍 <a class="header-anchor" href="#首先是个自我介绍" aria-label="Permalink to &quot;首先是个自我介绍&quot;">​</a></h2><p>这里是柳卿烟，一名普通（自称）的高中二年级学生，白天在教室里和函数搏斗，晚上在小屏幕前和老师们的日程表搏斗——是的，我说的是<strong>蔚蓝档案</strong>。</p><p>博客的用途大概是这些：</p><ul><li>📺 追番扫雷报告（季节性爆发）</li><li>🎮 蔚蓝档案的活动记录与抽卡忏悔录</li><li>🎧 通学路上的歌单分享</li><li>📚 月考生存实录（主要是吐槽）</li><li>🔧 折腾博客本身的记录</li></ul><h2 id="这个站有什么" tabindex="-1">这个站有什么 <a class="header-anchor" href="#这个站有什么" aria-label="Permalink to &quot;这个站有什么&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">功能清单</p><ul><li><strong>搜索</strong>：右上角放大镜，全站文章秒搜</li><li><strong>夜间模式</strong>：右上角开关，晚自习偷偷看也不刺眼（不要学）</li><li><strong>看板娘</strong>：右下角的阿罗娜，会跟着鼠标转头，点点她有语音</li><li><strong>点击特效</strong>：随便点点屏幕试试，很解压</li><li><strong>评论</strong>：每篇文章底部，GitHub 登录就能发言</li></ul></div><h2 id="关于更新频率" tabindex="-1">关于更新频率 <a class="header-anchor" href="#关于更新频率" aria-label="Permalink to &quot;关于更新频率&quot;">​</a></h2><details><summary>点开查看一份非常诚实的承诺</summary><p>理想状态：每周一更。 现实状态：月考周停更，活动周连更，假期爆更，开学吃灰。 总之，随缘但不断更（大概）。</p></details><div class="warning custom-block"><p class="custom-block-title">免责声明</p><p>本站所有内容都是一个高中生的个人视角，观点主观、口癖严重、语法偶有翻车。如果和你意见不合，欢迎评论区分对错（划掉）交流。</p></div><p>那么，欢迎来到我的基地。上课铃响了，先溜了——</p>',12)])])}const u=e(s,[["render",i]]);export{h as __pageData,u as default};
